import random

n = 27

def autocorr(x, n):
    res = []
    for k in range(1, n//2+1):
        s = 0
        for i in range(n):
            s += x[i]*x[(i+k)%n]
        res.append(s)
    return tuple(res)

random.seed(42)

table = {}

def random_seq():
    s = [1]*14 + [-1]*13
    random.shuffle(s)
    return s

def target(ax):
    return tuple(-2-v for v in ax)

found = None
for trial in range(500000):
    x = random_seq()
    ax = autocorr(x, n)
    ty = target(ax)
    if ty in table:
        found = (table[ty], x)
        break
    table[ax] = x
    if trial % 50000 == 0:
        print(trial, len(table))

print("found:", found is not None)
if found:
    x, y = found
    print("x =", x)
    print("y =", y)
    print("sum x:", sum(x), "sum y:", sum(y))
    ax = autocorr(x, n)
    ay = autocorr(y, n)
    print("ax+ay:", [a+b for a,b in zip(ax,ay)])

