from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

# Variables: x[i][j][v] = 1 if cell (i,j) has value v
N = 10
def var(i,j,v):
    return i*100 + j*10 + v + 1

solver = Glucose4()

# Each cell has exactly one value
for i in range(N):
    for j in range(N):
        lits = [var(i,j,v) for v in range(N)]
        solver.add_clause(lits)
        for a in range(N):
            for b in range(a+1,N):
                solver.add_clause([-lits[a], -lits[b]])

# Each row has each value exactly once
for i in range(N):
    for v in range(N):
        lits = [var(i,j,v) for j in range(N)]
        solver.add_clause(lits)
        for a in range(N):
            for b in range(a+1,N):
                solver.add_clause([-lits[a], -lits[b]])

# Each column has each value exactly once
for j in range(N):
    for v in range(N):
        lits = [var(i,j,v) for i in range(N)]
        solver.add_clause(lits)
        for a in range(N):
            for b in range(a+1,N):
                solver.add_clause([-lits[a], -lits[b]])

# Clues
for idx, val in enumerate(clues):
    if val != -1:
        i, j = idx // 10, idx % 10
        solver.add_clause([var(i,j,val)])

if solver.solve():
    model = set(solver.get_model())
    grid = [0]*100
    for i in range(N):
        for j in range(N):
            for v in range(N):
                if var(i,j,v) in model:
                    grid[i*10+j] = v
    print(grid)
    # verify
    for i in range(N):
        assert set(grid[i*10:(i+1)*10]) == set(range(10))
    for j in range(N):
        assert set(grid[i*10+j] for i in range(N)) == set(range(10))
    print("OK")
else:
    print("UNSAT")

