from collections import defaultdict, deque
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}; parent={s:-1}
        q=deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
                elif parent[u]!=v:
                    g=min(g, dist[u]+dist[v]+1)
    return g

