    # BFS from each vertex to detect cycle of length <= max_len
    for s in range(n):
        # BFS
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] <= max_len//2:
                            nq.append(v)
