                            break
                        nq.append(y)
                if found>0: break
            if found>0: break
            q=nq
        adj[u].add(v); adj[v].add(u)
        if found>0 and found+1 <=6:
            return False
    return True

def is_3colorable(edges, n):
    # Use backtracking
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    color = [-1]*n
    def bt(v):
        if v==n: return True
        used = set()
        for u in adj[v]:
            if color[u]>=0: used.add(color[u])
        for c in range(3):
            if c not in used:
                color[v]=c
                if bt(v+1): return True
        color[v]=-1
        return False
    return bt(0)

