def girth_at_least_6_after(adj, u, v):
    # returns True if adding edge u-v keeps girth >= 6, i.e., current dist(u,v) >= 5
    if v in adj[u]:
        return False
    # BFS from u, limit 4
    dist = {u: 0}
    q = [u]
    for d in range(1, 5):
        nq = []
        for x in q:
            for y in adj[x]:
                if y not in dist:
                    dist[y] = d
                    if y == v:
                        return False
                    nq.append(y)
