def girth_at_least_6(adj, n):
    # BFS from each vertex, find shortest cycle
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            new_q = []
            for u in queue:
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        if dist[v] < 3:
                            new_q.append(v)
                    elif parent[u] != v:
                        # found cycle of length dist[u] + dist[v] + 1
                        cyc = dist[u] + dist[v] + 1
                        if cyc < 6:
                            return False
            queue = new_q
    return True

def has_short_cycle(adj, n):
    # Check no cycle of length < 6 through any edge
    # For each edge (u,v), check if there's a path of length <= 4 from u to v not using edge
    for u in range(n):
        for v in adj[u]:
            if v <= u: continue
            # BFS from u, avoiding edge uv
            dist = {u: 0}
            queue = [u]
            for _ in range(4):
                new_q = []
                for x in queue:
                    for y in adj[x]:
                        if x == u and y == v: continue
                        if x == v and y == u: continue
                        if y not in dist:
                            dist[y] = dist[x] + 1
                            new_q.append(y)
                queue = new_q
            if v in dist and dist[v] <= 4:
                return True
    return False

