def check_girth_6(adj, n):
    # BFS from each vertex, check no cycle of length < 6
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nxt = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < 3:
                            nxt.append(v)
                    elif dist[v] == dist[u] and v != parent[u]:
                        # odd cycle of length 2*dist[u]+1
                        if 2*dist[u]+1 < 6:
                            return False
                    elif dist[v] == dist[u]+1 and parent[v] != u:
                        # even cycle of length 2*dist[u]+2
                        if 2*dist[u]+2 < 6:
                            return False
            queue = nxt
    return True

def try_build(seed):
