n = 22

def has_k5(adj, nodes):
    # check if any 5-clique exists in graph defined by adj (set of edges) restricted to nodes
    # use bron-kerbosch or just search
    # fast check: iterate
    neighbors = {v: set() for v in nodes}
    for (a,b) in adj:
        if a in neighbors and b in neighbors:
            neighbors[a].add(b)
            neighbors[b].add(a)
    # find 5-clique
    nodes_list = sorted(nodes)
    for a in nodes_list:
        Na = neighbors[a]
        for b in Na:
            if b<=a: continue
            Nb = Na & neighbors[b]
            for c in Nb:
                if c<=b: continue
                Nc = Nb & neighbors[c]
                for d in Nc:
                    if d<=c: continue
                    Nd = Nc & neighbors[d]
                    for e in Nd:
                        if e<=d: continue
                        return True
    return False

def check_coloring(colors):
    # colors: dict (i,j)->0/1 for i<j
    red = set()
    blue = set()
    for (i,j),c in colors.items():
        if c==0: red.add((i,j))
        else: blue.add((i,j))
    if has_k5(red, set(range(n))): return False
    if has_k5(blue, set(range(n))): return False
    return True

# cyclic construction
def cyclic_coloring(S):
    colors = {}
    for i in range(n):
        for j in range(i+1,n):
            d = min((j-i)%n, (i-j)%n)
            colors[(i,j)] = 0 if d in S else 1
    return colors

